-- The full Psychology library in one batch. Written in plain English on
-- purpose: short questions, common words, and no idioms, so the wording never
-- gets in the way. Psychology terms themselves are kept -- they are the point.
-- The subject labels support later review and balancing; they are not shown in the UI.
insert into public.quiz_questions (
  id,
  category_id,
  prompt,
  correct_answer,
  wrong_answers,
  language_code,
  grade_level,
  subject,
  display_order,
  is_active
)
select
  'psychology_' || lpad(question.ordinality::text, 4, '0'),
  'psychology',
  question.item ->> 'p',
  question.item ->> 'a',
  array(select jsonb_array_elements_text(question.item -> 'w')),
  'en',
  null,
  question.item ->> 's',
  question.ordinality::integer,
  true
from jsonb_array_elements($questions$
