  {"s": "Emotion and Motivation", "p": "What does the James-Lange theory say?", "a": "The body reacts first, then you feel the emotion", "w": ["You feel the emotion before any body change", "Body and feeling happen at the same moment", "Emotions are only learned"]},
  {"s": "Emotion and Motivation", "p": "What does the Cannon-Bard theory say?", "a": "The body reaction and the feeling happen together", "w": ["The body always reacts first", "Feelings come long after the event", "Emotions do not involve the body"]},
  {"s": "Emotion and Motivation", "p": "What does the two-factor theory of emotion say?", "a": "Emotion needs body arousal plus a label for it", "w": ["Emotion needs no thought at all", "Emotion is purely physical", "Emotion is purely learned"]},
  {"s": "Emotion and Motivation", "p": "Who proposed the two-factor theory of emotion?", "a": "Schachter and Singer", "w": ["Cannon and Bard", "Watson and Rayner", "Piaget and Vygotsky"]},
  {"s": "Emotion and Motivation", "p": "What does the facial feedback idea suggest?", "a": "Your expression can influence how you feel", "w": ["Your face never shows emotion", "Feelings cannot be hidden", "Smiling has no effect at all"]},
  {"s": "Emotion and Motivation", "p": "Which set of emotions is often called universal?", "a": "Happiness, sadness, anger, fear, surprise, disgust", "w": ["Pride, shame, envy, guilt", "Boredom, hope, relief, awe", "Love, hate, trust, doubt"]},
  {"s": "Emotion and Motivation", "p": "Who studied facial expressions across cultures?", "a": "Paul Ekman", "w": ["Ivan Pavlov", "Albert Bandura", "Jean Piaget"]},
