  {"s": "People and Groups", "p": "What is conformity?", "a": "Changing your behaviour to match a group", "w": ["Following a direct order", "Helping a stranger", "Working alone"]},
  {"s": "People and Groups", "p": "Who ran the study where people judged line lengths in a group?", "a": "Solomon Asch", "w": ["Stanley Milgram", "Philip Zimbardo", "Albert Bandura"]},
  {"s": "People and Groups", "p": "What did Asch's line study show?", "a": "People often agree with a majority that is clearly wrong", "w": ["People never change their answers", "People always trust their own eyes", "Groups always find the right answer"]},
  {"s": "People and Groups", "p": "What is obedience?", "a": "Following instructions from an authority figure", "w": ["Copying a friend's clothing", "Agreeing with a group", "Helping in an emergency"]},
