  {"s": "People and Groups", "p": "What is group polarisation?", "a": "A group's shared views becoming more extreme", "w": ["A group reaching a mild compromise", "A group splitting in half", "A group falling silent"]},
  {"s": "People and Groups", "p": "What is the foot-in-the-door technique?", "a": "Asking a small favour first, then a bigger one", "w": ["Asking a huge favour first", "Refusing all requests", "Offering a gift first"]},
  {"s": "People and Groups", "p": "What is the door-in-the-face technique?", "a": "Asking a very large favour first, then a smaller one", "w": ["Asking a small favour first", "Slamming a door in anger", "Ignoring a request"]},
