$questions$::jsonb) with ordinality as question(item, ordinality);

do $validation$
begin
  if (
    select count(*)
    from public.quiz_questions
    where category_id = 'psychology'
      and is_active
  ) <> 602 then
    raise exception 'Psychology must contain exactly 602 active questions';
  end if;

  if exists (
    select 1
    from public.quiz_questions as question
    where question.category_id = 'psychology'
      and (
        cardinality(question.wrong_answers) <> 3
        or (
          select count(distinct lower(trim(answer)))
          from unnest(question.wrong_answers) as answer
        ) <> 3
        or exists (
          select 1
          from unnest(question.wrong_answers) as answer
          where lower(trim(answer)) = lower(trim(question.correct_answer))
        )
      )
  ) then
    raise exception 'Every Psychology question must have three distinct wrong answers';
  end if;

  if exists (
    select 1
    from public.quiz_questions as proposed
    join public.quiz_questions as existing
      on lower(trim(existing.prompt)) = lower(trim(proposed.prompt))
     and existing.id <> proposed.id
    where proposed.category_id = 'psychology'
  ) then
    raise exception 'Psychology contains a prompt already used by another question';
  end if;
end;
$validation$;
